  "omnichannel.settings.apiIntegration.docs.httpCodes.200.detail": "Permintaan berhasil — mis. heartbeat traffic, click/WA link, atau update tanpa baris utama baru.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.201.label": "Dibuat",
  "omnichannel.settings.apiIntegration.docs.httpCodes.201.detail": "Resource baru tersimpan — lead + profil, sesi/page view traffic, atau baris invoice.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.400.label": "Permintaan tidak valid",
  "omnichannel.settings.apiIntegration.docs.httpCodes.400.detail": "Body bukan JSON valid. Kirim `Content-Type: application/json` dengan objek yang bisa di-parse.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.401.label": "Tidak terotorisasi",
  "omnichannel.settings.apiIntegration.docs.httpCodes.401.detail": "Header `Authorization: Bearer` hilang, format token salah (`sk_omni_…`), atau hash token tidak dikenali. Buat token baru di **Token & SDK**.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.403.label": "Dilarang",
  "omnichannel.settings.apiIntegration.docs.httpCodes.403.detail": "Token **dicabut** (`is_active: false`), **kedaluwarsa**, **scope tidak cocok** (mis. token SDK memanggil invoice-trigger), atau **request browser** pada invoice (`code: BROWSER_REQUEST_REJECTED` jika header `Origin` / `Sec-Fetch-Site` terdeteksi). Terbitkan token dengan tipe yang benar; invoice hanya dari backend.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.404.label": "Tidak ditemukan",
  "omnichannel.settings.apiIntegration.docs.httpCodes.404.detail": "Path tidak dikenal di base URL API publik. Periksa segmen path (mis. `/leads`, `/traffic/session`).",
  "omnichannel.settings.apiIntegration.docs.httpCodes.405.label": "Metode tidak diizinkan",
  "omnichannel.settings.apiIntegration.docs.httpCodes.405.detail": "Hanya **POST** (dan **OPTIONS** untuk CORS preflight) yang didukung. Jangan pakai GET/PUT/PATCH/DELETE.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.409.label": "Konflik",
  "omnichannel.settings.apiIntegration.docs.httpCodes.409.detail": "`invoice_number` duplikat untuk organisasi ini. Gunakan nomor unik atau anggap sukses idempoten jika invoice sudah pernah dikirim.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.422.label": "Validasi gagal",
  "omnichannel.settings.apiIntegration.docs.httpCodes.422.detail": "Field wajib hilang atau tidak valid (mis. `name`, `phone_number`/`email`, UUID `session_id`, `amount` positif, `items` tidak kosong). Baca `error` dan `details` di body respons.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.429.label": "Rate limit",
  "omnichannel.settings.apiIntegration.docs.httpCodes.429.detail": "Lebih dari **100 permintaan per menit** per token (jendela menit UTC). Tunggu lalu coba lagi; batch event traffic jika memungkinkan.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.500.label": "Kesalahan server",
  "omnichannel.settings.apiIntegration.docs.httpCodes.500.detail": "Gagal tidak terduga saat menyimpan data. Coba ulang payload yang sama; hubungi dukungan jika berlanjut.",
  "omnichannel.settings.apiIntegration.docs.httpCodes.503.label": "Layanan tidak tersedia",
  "omnichannel.settings.apiIntegration.docs.httpCodes.503.detail": "Lingkungan edge function belum dikonfigurasi (service role Supabase hilang). Bukan masalah payload klien.",
  "omnichannel.settings.apiIntegration.docs.checklist.token": "Dua token per `web_id`: **SDK** (allowed origins terisi, di website) + **Server** (backend secrets). Scope token + blok browser pada invoice ditegakkan API.",
  "omnichannel.settings.apiIntegration.docs.checklist.sdk": "Snippet SDK memakai **token SDK** di website; tombol CTA memakai `data-syn-track` untuk atribusi klik.",
  "omnichannel.settings.apiIntegration.docs.checklist.form": "Form lead memanggil `SynckerjaTrackLead` (objek flat atau legacy 4-arg); sertakan `session_id` dari SDK untuk atribusi traffic.",
  "omnichannel.settings.apiIntegration.docs.checklist.invoice": "Invoice **hanya** dari backend (Edge Function/server) dengan **token Server** — jangan `fetch` di halaman web; cek Sales Activities dan `whatsapp_status`.",
